declare(strict_types=1);

use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Domain\ValueObject\Holder\DcrInitialAccessTokenRevokedAtAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the DcrInitialAccessTokenRevokedAtAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class DcrInitialAccessTokenRevokedAtAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getRevokedAt returns null on a freshly created holder.
     */
    public function testRevokedAtNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithDcrInitialAccessTokenRevokedAtAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isRevokedAtAssigned());
        $this->assertNull($holder->getRevokedAt());
    }
}
class ImplWithDcrInitialAccessTokenRevokedAtAttributeHolderUnitTest
{
    use DcrInitialAccessTokenRevokedAtAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedRevokedAtRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultRevokedAt();
    }
}
